-- ===========================================================================
-- PUSH — إضافة الجامعات (11 جامعة) والمساقات مع أرقامها/رموزها (587 مساقًا)
-- قابل لإعادة التنفيذ بأمان (Idempotent) — يستخدم معرّفات UUID حتمية.
-- نفّذ هذا الملف في Supabase SQL Editor بعد تنفيذ supabase_schema_latest.sql
-- ===========================================================================
begin;

-- 1) إدراج الجامعات الفلسطينية
on conflict (id) do update set name_ar = excluded.name_ar;

-- 2) إدراج المساقات الدراسية مع أرقامها/رموزها (code)
on conflict (id) do update set name_ar = excluded.name_ar, code = excluded.code, university_id = excluded.university_id;

commit;
